-- pointInPolygon with a constant polygon must return the same results as with a non-constant polygon.

-- A diamond.
SELECT pointInPolygon((0.76, 0.01), [(1., 0.), (0., 1.), (-1., 0.), (0., -1.)]);
SELECT pointInPolygon((0.05, -0.9), [(1., 0.), (0., 1.), (-1., 0.), (0., -1.)]);
-- Triangles with a vertex at a corner of the bounding box.
SELECT pointInPolygon((0.49, -0.13), [(-0.5, 0.75), (-0.5, 0.25), (0.5, -0.25)]);
SELECT pointInPolygon((0.01, 0.55), [(0.5, 1.), (0., 0.5), (0., 0.75)]);
-- A 16-gon computed with sin and cos.
SELECT pointInPolygon((-0.01, -1.2), [(1, 0), (1.0299455496892689, 0.42661741518710766), (0.55710678118654755, 0.55710678118654744), (0.48874944954307203, 1.179945549689269), (4.286263797015736e-17, 0.69999999999999996), (-0.48874944954307176, 1.1799455496892688), (-0.55710678118654744, 0.55710678118654755), (-1.0299455496892684, 0.42661741518710761), (-1.0000000000000002, 1.2246467991473535e-16), (-0.81781351533330471, -0.33874944954307185), (-0.85710678118654804, -0.85710678118654782), (-0.27661741518710786, -0.66781351533330402), (-2.3880612583373386e-16, -1.3), (0.27661741518710764, -0.66781351533330402), (0.85710678118654671, -0.85710678118654715), (0.81781351533330615, -0.33874944954307312)]);
-- Small holes.
SELECT pointInPolygon((3.1, 3.1), [[(0., 0.), (8., 0.), (8., 8.), (0., 8.)], [(3.2, 3.2), (3.8, 3.2), (3.8, 3.8), (3.2, 3.8)]]);
SELECT pointInPolygon((3.2, 3.2), [[(0., 0.), (8., 0.), (8., 8.), (0., 8.)], [(3.1, 3.1), (3.3, 3.1), (3.3, 3.3), (3.1, 3.3)]]);
SELECT pointInPolygon((3.2, 3.2), [[[(0., 0.), (8., 0.), (8., 8.), (0., 8.)], [(3.1, 3.1), (3.3, 3.1), (3.3, 3.3), (3.1, 3.3)]]]);
SELECT pointInPolygon((3.2, 3.2), [(0., 0.), (8., 0.), (8., 8.), (0., 8.)], [(3.1, 3.1), (3.3, 3.1), (3.3, 3.3), (3.1, 3.3)]);

-- The number of points of a lattice where the constant and the non-constant polygon disagree.
SELECT countIf(pointInPolygon((x, y), [(1., 0.), (0., 1.), (-1., 0.), (0., -1.)]) != pointInPolygon((x, y), materialize([(1., 0.), (0., 1.), (-1., 0.), (0., -1.)]))) FROM (SELECT -1.05 + (number % 100 + 0.31830988618) * 0.021 AS x, -1.05 + (intDiv(number, 100) + 0.41421356237) * 0.021 AS y FROM numbers(10000));
SELECT countIf(pointInPolygon((x, y), [(-0.5, 0.75), (-0.5, 0.25), (0.5, -0.25)]) != pointInPolygon((x, y), materialize([(-0.5, 0.75), (-0.5, 0.25), (0.5, -0.25)]))) FROM (SELECT -0.55 + (number % 100 + 0.31830988618) * 0.011 AS x, -0.3 + (intDiv(number, 100) + 0.41421356237) * 0.011 AS y FROM numbers(10000));
SELECT countIf(pointInPolygon((x, y), [(0.5, 1.), (0., 0.5), (0., 0.75)]) != pointInPolygon((x, y), materialize([(0.5, 1.), (0., 0.5), (0., 0.75)]))) FROM (SELECT -0.05 + (number % 100 + 0.31830988618) * 0.006 AS x, 0.45 + (intDiv(number, 100) + 0.41421356237) * 0.006 AS y FROM numbers(10000));
SELECT countIf(pointInPolygon((x, y), [(1, 0), (1.0299455496892689, 0.42661741518710766), (0.55710678118654755, 0.55710678118654744), (0.48874944954307203, 1.179945549689269), (4.286263797015736e-17, 0.69999999999999996), (-0.48874944954307176, 1.1799455496892688), (-0.55710678118654744, 0.55710678118654755), (-1.0299455496892684, 0.42661741518710761), (-1.0000000000000002, 1.2246467991473535e-16), (-0.81781351533330471, -0.33874944954307185), (-0.85710678118654804, -0.85710678118654782), (-0.27661741518710786, -0.66781351533330402), (-2.3880612583373386e-16, -1.3), (0.27661741518710764, -0.66781351533330402), (0.85710678118654671, -0.85710678118654715), (0.81781351533330615, -0.33874944954307312)]) != pointInPolygon((x, y), materialize([(1, 0), (1.0299455496892689, 0.42661741518710766), (0.55710678118654755, 0.55710678118654744), (0.48874944954307203, 1.179945549689269), (4.286263797015736e-17, 0.69999999999999996), (-0.48874944954307176, 1.1799455496892688), (-0.55710678118654744, 0.55710678118654755), (-1.0299455496892684, 0.42661741518710761), (-1.0000000000000002, 1.2246467991473535e-16), (-0.81781351533330471, -0.33874944954307185), (-0.85710678118654804, -0.85710678118654782), (-0.27661741518710786, -0.66781351533330402), (-2.3880612583373386e-16, -1.3), (0.27661741518710764, -0.66781351533330402), (0.85710678118654671, -0.85710678118654715), (0.81781351533330615, -0.33874944954307312)]))) FROM (SELECT -1.1 + (number % 300 + 0.31830988618) * 2.2 / 300 AS x, -1.35 + (intDiv(number, 300) + 0.41421356237) * 2.6 / 300 AS y FROM numbers(90000));
SELECT countIf(pointInPolygon((x, y), [[(0., 0.), (8., 0.), (8., 8.), (0., 8.)], [(3.1, 3.1), (3.3, 3.1), (3.3, 3.3), (3.1, 3.3)]]) != pointInPolygon((x, y), materialize([[(0., 0.), (8., 0.), (8., 8.), (0., 8.)], [(3.1, 3.1), (3.3, 3.1), (3.3, 3.3), (3.1, 3.3)]]))) FROM (SELECT 3 + (number % 100 + 0.31830988618) * 0.01 AS x, 3 + (intDiv(number, 100) + 0.41421356237) * 0.01 AS y FROM numbers(10000));
-- A reflex vertex, a band and a slot.
SELECT countIf(pointInPolygon((x, y), [(0., 0.), (4.5, 2.5), (8., 0.), (4., 8.)]) != pointInPolygon((x, y), materialize([(0., 0.), (4.5, 2.5), (8., 0.), (4., 8.)]))) FROM (SELECT 4 + (number % 100 + 0.31830988618) * 0.01 AS x, 2 + (intDiv(number, 100) + 0.41421356237) * 0.01 AS y FROM numbers(10000));
SELECT countIf(pointInPolygon((x, y), [(0., 0.), (0.5, 0.), (8., 7.5), (8., 8.), (7.5, 8.), (0., 0.5)]) != pointInPolygon((x, y), materialize([(0., 0.), (0.5, 0.), (8., 7.5), (8., 8.), (7.5, 8.), (0., 0.5)]))) FROM (SELECT 3 + (number % 100 + 0.31830988618) * 0.01 AS x, 3 + (intDiv(number, 100) + 0.41421356237) * 0.01 AS y FROM numbers(10000));
SELECT countIf(pointInPolygon((x, y), [(0., 0.), (8., 0.), (8., 8.), (4.6, 8.), (4.6, 2.), (4.4, 2.), (4.4, 8.), (0., 8.)]) != pointInPolygon((x, y), materialize([(0., 0.), (8., 0.), (8., 8.), (4.6, 8.), (4.6, 2.), (4.4, 2.), (4.4, 8.), (0., 8.)]))) FROM (SELECT 4 + (number % 100 + 0.31830988618) * 0.01 AS x, 4 + (intDiv(number, 100) + 0.41421356237) * 0.01 AS y FROM numbers(10000));
